Method.Implementation:
	// To test exception
	// set retVal = "Unknown"
    // THROW ##class(%Exception.General).%New("Exception","999","Testing","My own special exception")

	 // Don't assume parameters will exist
	 if $G(repInt) = ""
	 {
		 Write !, "paramater is NULL"
		 Quit retVal
	 }
	 // Check if the value is valid
	 if ( ##class(%Library.Integer).IsValid(repInt) '= $$$OK)
  	 {
	   Write !, "paramater is Invalid number"
		 Quit retVal
     }

  Write !, "Val: ", repInt
  set rep = "" _ repInt
  // set rep = %Library.Integer.LogicalToDisplay(repInt)
  Write !, "creating WS class to get NCID for " _ rep
  // Imported the WSDL using Tools -> Add Ins -> SOAP Wizard
  // WSDL:  http://tacweb-test.co.ihc.com/HddWebServicesExt/HddCommonService?wsdl
  //
 set servicePort = ##class(HddCommonService.HddCommonServicePort).%New()

 // To change the environment call
 // set servicePort.Location = "http://tacweb.co.ihc.com:80/HddWebServicesExt/HddCommonService"
 try {
  Set file=##class(%File).%New("/usr/local/tmp/jay/CallHDD.txt")

	Do file.Open("WSN")
	Do file.WriteLine("Get Ncid for " _ rep)


	// Write !, "HOROLOG: ", $HOROLOG
	Do file.WriteLine( "TODAY: " _ $zdate($h))
 	Set list = servicePort.getNcidsForRepresentation(rep, "106415", "50035", "tst") ; 119
 	set prntStr =  "Call returned " _ list.Count()
 	Do file.WriteLine(prntStr)
 	if (list.Count() < 1)
 	{
	 	   Do ##class(Ens.Util.Log).LogError("DemoJayHL7.CallHdd","CallHDD","Ncid " _ repInt _ ": " _ retVal)

 	}
 	else
 	{
 	For cnt=1:1:list.Count() 
 	{
		  Write !, "NCID for : ", rep, " = ", list.GetAt(cnt)
		  Do file.WriteLine("NCID for : " _ rep _ " = " _ list.GetAt(cnt))
		  Set ced = servicePort.getPreferredSurfaceForm(list.GetAt(cnt), "520733357", "tst")
		  if $GET(ced)
		  {
		  	Write !, "   Pref Name in HELP context for: ",list.GetAt(cnt), " = ", ced.text
		  	Do file.WriteLine("Pref Name in HELP context for: " _list.GetAt(cnt) _ " = " _ ced.text)
		  	Set retVal = list.GetAt(cnt)
		  	Write !, "ret val: ", retVal
		  	Quit
		  }
		  else
		  {
			  	Write !, "   In diff context"
			Set ced = servicePort.getPreferredSurfaceForm(list.GetAt(cnt), "50450833", "tst")
		 	if $GET(ced)
		  	{
		  		Write !, "   Set in Centricity context for: ",list.GetAt(cnt), " = ", ced.text
		  		Do file.WriteLine("Set Name in Centricity context for: " _ list.GetAt(cnt) _ " = " _ ced.text)
		  		Set retVal = list.GetAt(cnt)
		  		Write !, "ret val: ", retVal
		  		Quit
		  	}

		  }

 	 }
 Do file.Close()
 	}
	}  CATCH exceptionvar
  {
      Do file.WriteLine("this is the error routine")
     // Do file.WriteLine("the error was: " _ $ZERROR)
  }

  // Do ##class(Ens.Util.Log).Log(4, "DemoJayHL7.CallHdd","CallHDD","Ncid " _ repInt _ ": " _ retVal)
  Quit retVal
